#!/bin/zsh
# Build and validate the extension zip: dist/<id>-<version>.zip
# Generated by UVReady's tools/build_lite.py.
HERE=${0:A:h}
PKG="$HERE/uvready_lite"
ID=$(sed -n 's/^id = "\(.*\)"/\1/p' "$PKG/blender_manifest.toml")
VER=$(sed -n 's/^version = "\(.*\)"/\1/p' "$PKG/blender_manifest.toml")
ZIP="$HERE/dist/$ID-$VER.zip"
mkdir -p "$HERE/dist"; rm -f "$ZIP"
find "$PKG" -name __pycache__ -type d -prune -exec rm -rf {} +
bl() { local x; for try in $(seq 1 240); do "$HERE/tests/bl.sh" 52 build "$@"; x=$?; [[ $x == 75 || $x == 137 ]] || return $x; sleep 60; done; return $x }   # 75/137: memory guard, wait
bl --command extension build --source-dir "$PKG" --output-dir "$HERE/dist" || exit 1
bl --command extension validate "$ZIP" || exit 1
for f in LICENSE pipeline/autouv.py pipeline/uvlab.py core.py; do
  unzip -l "$ZIP" | grep -q " $f\$" || { echo "MISSING in the zip: $f"; exit 1 }
done
# no binaries: only text files may be inside
bad=$(unzip -Z1 "$ZIP" | grep -vE '\.(py|toml|json)$|(^|/)LICENSE$')
[[ -n $bad ]] && { echo "NON-TEXT files in the zip: $bad"; exit 1 }
echo "BUILT $ZIP ($(stat -f %z "$ZIP") bytes, $(unzip -Z1 "$ZIP" | wc -l | tr -d ' ') files, no binaries)"
